export default {
  methods: {
    getBorderOfElement(element, formBuilderConfigModel) {
      let border = '';
      if (
        formBuilderConfigModel &&
        formBuilderConfigModel.hasOwnProperty(element.name)
      ) {
        border = formBuilderConfigModel[element.name].right_border
          ? ' border-right'
          : '';

        border += formBuilderConfigModel[element.name].bottom_border
          ? ' border-bottom'
          : '';

        return border;
      }

      border = element.right_border ? ' border-right' : '';

      border += element.bottom_border ? ' border-bottom' : '';

      return border;
    },
  },
};
